            open_count += 1
        elif char == ')':
            close_count += 1

    # Check if the number of opening brackets is equal to the number of closing brackets
    if open_count != close_count:
        return False

    # Iterate through the input string and check if each opening bracket is matched by a closing bracket
    stack = []
    for char in brackets:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()

    # Return True if all conditions are satisfied, otherwise return False
    return len(stack) == 0
